        this.y = Y;
        this.z = Z;
    }

    public override bool Equals(Object obj)
    {
        if (!(obj is Point))
        {
            return false;
        }

        if (((Point)obj).x == this.x)
        {
            return true;
        }

        return false;
    }
    public bool Equals(Point obj)
    {
