    //运算符“Point.operator ==(Point, Point)”要求也要定义匹配的运算符“!=”
    public static bool operator ==(Point left, Point right)
    {
        return left.x == right.x;
    }

    public static bool operator !=(Point left, Point right)
    {
        return left.x != right.x;
    }
