using (FileStream fs = new FileStream("File.FileStream", FileMode.Create, FileAccess.Write))
{
    for (int i = 0; i < Cycles; i++)
    {
        for (int j = 0; j < Length; j++)
        {
            dis[j] = i * Length + j;
