    [System.ComponentModel.Description("星期三")]
    Wednesday,

    [System.ComponentModel.Description("星期四")]
    Thursday,

    [System.ComponentModel.Description("星期五")]
    Firday,

    [System.ComponentModel.Description("星期六")]
    Saturday,

    [System.ComponentModel.Description("星期日")]
    Sunday,
}
